def count_prefix_suffix_pairs(words):
    trie={};answer=0
    for word in words:
        node=trie
        for pair in zip(word,reversed(word)):
            node=node.setdefault(pair,{})
            answer+=node.get(None,0)
        node[None]=node.get(None,0)+1
    return answer

